import { gsap } from 'gsap';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, vec2, float, uniform, color, normalMap, emissive } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Root group for the entire footer
  const root = new THREE.Group();
  root.name = 'footer-colophon';

  // ===== STAGE BACKDROP (gradient plane) =====
  const stageGeom = new THREE.PlaneGeometry(6.8, 2.0);
  const stageMat = new MeshStandardNodeMaterial();

  // Gradient from #121218 to #0b0b10
  const colorTop = vec3(0.071, 0.071, 0.098);    // #121218
  const colorBottom = vec3(0.043, 0.043, 0.063); // #0b0b10
  const gradientNode = mix(colorTop, colorBottom, uv().y);

  stageMat.colorNode = gradientNode;
  stageMat.roughnessNode = float(0.6);
  stageMat.metalnessNode = float(0.2);
  stageMat.emissiveNode = vec3(0, 0, 0);

  const stagePlane = new THREE.Mesh(stageGeom, stageMat);
  stagePlane.position.z = 0;
  root.add(stagePlane);

  // ===== TOP HAIRLINE RULE (emissive accent edge) =====
  const topRuleGeom = new THREE.PlaneGeometry(6.8, 0.006);
  const ruleMat = new MeshStandardNodeMaterial();
  ruleMat.colorNode = vec3(0.137, 0.137, 0.173); // #23232b
  ruleMat.emissiveNode = vec3(0.137, 0.137, 0.173);
  ruleMat.emissiveIntensity = 0.8;
  ruleMat.roughnessNode = float(0.3);
  ruleMat.metalnessNode = float(0.4);

  const topRule = new THREE.Mesh(topRuleGeom, ruleMat);
  topRule.position.z = 0.01;
  topRule.position.y = 1.0 - 0.003; // Top edge of footer
  root.add(topRule);

  // ===== BOTTOM HAIRLINE RULE =====
  const bottomRule = new THREE.Mesh(topRuleGeom, ruleMat.clone());
  bottomRule.position.z = 0.01;
  bottomRule.position.y = -1.0 + 0.375 + 0.003; // Above legal text
  root.add(bottomRule);

  // ===== WORDMARK BLOCK (left 2.0 units) =====
  const wordmarkGroup = new THREE.Group();
  wordmarkGroup.position.x = -3.4;
  wordmarkGroup.position.y = 0.3;

  // Wordmark text: "NOVA ATELIER"
  const wordmarkText = ctx.fontAtlas.createText('NOVA ATELIER', {
    fontSize: 34,
    color: '#e8ecf2',
    align: 'left',
  });
  wordmarkText.position.y = 0.3;
  wordmarkText.position.z = 0.02;
  wordmarkGroup.add(wordmarkText);

  // Accent bar beneath wordmark (#ff2a38 emissive 1.4)
  const accentBarGeom = new THREE.PlaneGeometry(0.3, 0.02);
  const accentMat = new MeshStandardNodeMaterial();
  accentMat.colorNode = vec3(1.0, 0.165, 0.220); // #ff2a38
  accentMat.emissiveNode = vec3(1.0, 0.165, 0.220);
  accentMat.emissiveIntensity = 1.4;
  accentMat.roughnessNode = float(0.2);
  accentMat.metalnessNode = float(0.7);

  const accentBar = new THREE.Mesh(accentBarGeom, accentMat);
  accentBar.position.y = 0.0;
  accentBar.position.z = 0.02;
  wordmarkGroup.add(accentBar);

  root.add(wordmarkGroup);

  // ===== THREE LINK COLUMNS (right side) =====
  const columnData = [
    { header: 'ATELIER', links: ['Features', 'Collection', 'Pricing'] },
    { header: 'COMPANY', links: ['Journal', 'Visit the Atelier', 'Contact'] },
    { header: 'LEGAL', links: ['Privacy', 'Terms', 'Warranty'] },
  ];

  const columnWidth = 1.2;
  const gutter = 0.375;
  const startX = -3.4 + 2.0 + gutter;

  columnData.forEach((col, colIdx) => {
    const columnGroup = new THREE.Group();
    columnGroup.position.x = startX + (columnWidth + gutter) * colIdx;
    columnGroup.position.y = 0.4;

    // Column header
    const headerText = ctx.fontAtlas.createText(col.header, {
      fontSize: 9,
      color: '#b8bcc8',
      align: 'left',
    });
    headerText.position.y = 0.25;
    headerText.position.z = 0.02;
    columnGroup.add(headerText);

    // Links (1.8 line height = ~0.234 units @ fontSize 13)
    col.links.forEach((linkText, linkIdx) => {
      const link = ctx.fontAtlas.createText(linkText, {
        fontSize: 13,
        color: '#e8ecf2',
        align: 'left',
      });
      link.position.y = 0.25 - 0.234 * (linkIdx + 1);
      link.position.z = 0.02;

      // Attach hover handler
      link.userData.isInteractive = true;
      link.userData.handlers = link.userData.handlers || {};

      const originalColor = '#e8ecf2';
      const hoverColor = '#ff2a38';
      let hoverTimeline = null;

      link.userData.handlers.onHover = () => {
        if (hoverTimeline) hoverTimeline.kill();
        hoverTimeline = gsap.to(link.position, {
          z: 0.04,
          duration: 0.14,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        });
        gsap.to(link.material, {
          emissiveIntensity: 1.0,
          duration: 0.14,
        }, 0);
      };

      link.userData.handlers.onUnhover = () => {
        if (hoverTimeline) hoverTimeline.kill();
        hoverTimeline = gsap.to(link.position, {
          z: 0.02,
          duration: 0.14,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        });
        gsap.to(link.material, {
          emissiveIntensity: 0.0,
          duration: 0.14,
        }, 0);
      };

      columnGroup.add(link);
    });

    root.add(columnGroup);
  });

  // ===== LEGAL LINE (bottom) =====
  const legalText = ctx.fontAtlas.createText(
    '(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.',
    {
      fontSize: 9,
      color: '#9a9daa',
      align: 'left',
      maxWidthPx: 1200,
    }
  );
  legalText.position.x = -3.3;
  legalText.position.y = -1.0 + 0.375 - 0.125;
  legalText.position.z = 0.02;
  root.add(legalText);

  // ===== ENTRY ANIMATION =====
  root.position.y = 0.2;
  root.material = root.children.map(c => c.material);
  root.userData.animationTimeline = gsap.timeline();
  root.userData.animationTimeline.to(root.position, {
    y: 0,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  }, 0);
  root.userData.animationTimeline.to(root, {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  }, 0);

  root.userData.cleanup = () => {
    if (root.userData.animationTimeline) {
      root.userData.animationTimeline.kill();
    }
    stageMat.dispose();
    ruleMat.dispose();
    accentMat.dispose();
    stageGeom.dispose();
    topRuleGeom.dispose();
    accentBarGeom.dispose();
  };

  return root;
}
